<script setup lang="ts">import { onMounted,ref } from 'vue';import {adminApi} from '../services/api';const stats=ref<Record<string,number>>({});onMounted(async()=>{stats.value=await adminApi.dashboard();});const cards:[string,string][]=[['total','Client 數量'],['enabled','啟用'],['disabled','停用'],['recentSuccess','最近成功'],['recentFailure','最近失敗']];</script>
<template><h1 class="mb-6 text-2xl font-bold">Dashboard</h1><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><div v-for="[key,label] in cards" :key="key" class="card"><p class="text-sm text-slate-400">{{label}}</p><p class="mt-2 text-3xl font-bold">{{stats[key]??0}}</p></div></div></template>
